// tools/buildings/pipeline/fixtures.mjs - the shop fixtures' boards and the goods' footprints, measured (#1143).
//
// fixtures.json is generated by `tools\cli fixtures` from `tools\cli measure` (the .xob colliders of the
// vanilla gondola, cooler and counter, and of every item a spec's store sells). Nothing in it is typed by
// hand: the store stage reads it to place shelf points, the selftests check the script constants
// (LF_StoreComponent's snap distances, the snap test's board heights) against it.
//
//   fixtures[name].boards[]  { y: top of the board, z: [front-back extent], x: [left-right extent],
//                              clear: height to the next surface above (null = open) }, lowest first
//   items[path]              { size: [x, y, z] of the model's bounds, center: [x, z] of its footprint }
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join } from "node:path";

// A surface counts as a board when goods can stand on it: wide, deep and above the floor. A top lip
// (7 cm deep), the 15 cm step of a counter and the bin inside a cooler's floor are not boards.
export const MIN_WIDTH = 0.6;
export const MIN_DEPTH = 0.2;
export const MIN_Y = 0.09;
// Strips of one deck: same x span, touching in z, steps up to this much in y (a cooler's sloped deck).
const MERGE_DY = 0.06;
const MERGE_GAP = 0.03;
// A surface higher than the board only limits the goods' height where it covers this much depth of it.
const COVER_DEPTH = 0.05;

const r3 = (n) => Math.round(n * 1000) / 1000;
const overlap = (a, b) => Math.min(a[1], b[1]) - Math.max(a[0], b[0]);

// Pure: boards from the measured surfaces of one prefab, lowest first.
export function boardsOf(surfaces) {
  const cand = surfaces
    .filter((s) => s.x[1] - s.x[0] >= MIN_WIDTH && s.z[1] - s.z[0] >= MIN_DEPTH && s.y >= MIN_Y)
    .map((s) => ({ y: s.y, x: [...s.x], z: [...s.z] }))
    .sort((a, b) => a.y - b.y);
  const groups = [];
  for (const s of cand) {
    const g = groups.find((q) => Math.abs(s.y - q.top) <= MERGE_DY && overlap(s.x, q.x) > 0 && overlap(s.z, q.z) >= -MERGE_GAP);
    if (!g) {
      groups.push({ ...s, top: s.y });
      continue;
    }
    g.top = Math.max(g.top, s.y);
    g.y = g.top;
    g.x = [Math.min(g.x[0], s.x[0]), Math.max(g.x[1], s.x[1])];
    g.z = [Math.min(g.z[0], s.z[0]), Math.max(g.z[1], s.z[1])];
  }
  return groups.map((g) => {
    const above = surfaces
      .filter((s) => s.y > g.y + MERGE_DY && overlap(s.x, g.x) > 0 && overlap(s.z, g.z) >= COVER_DEPTH)
      .map((s) => s.y - g.y);
    return { y: r3(g.y), x: g.x.map(r3), z: g.z.map(r3), clear: above.length ? r3(Math.min(...above)) : null };
  });
}

// Pure: an item's footprint from its measured bounds.
export function itemOf(bounds) {
  const size = [0, 1, 2].map((k) => r3(bounds.max[k] - bounds.min[k]));
  return { size, center: [r3((bounds.max[0] + bounds.min[0]) / 2), r3((bounds.max[2] + bounds.min[2]) / 2)] };
}

// "{GUID}Prefabs/Items/Food/Apple.et" -> "Prefabs/Items/Food/Apple.et"
export const itemKey = (ref) => String(ref).replace(/^\{[0-9A-Fa-f]{16}\}/, "");

// Measured although no spec's store line stands goods on it: the snap test's counter (LF_Test_StoreSnapToBoard).
const ALSO = ["CounterShop_01"];

// The fixture prefabs and items the committed specs' store blocks name, and ALSO.
export function wanted(root) {
  const dir = join(root, "tools", "buildings");
  const fixtures = new Set(ALSO);
  const items = new Set();
  for (const d of readdirSync(dir, { withFileTypes: true })) {
    const f = join(dir, d.name, "spec.json");
    if (!d.isDirectory() || !existsSync(f)) continue;
    const store = JSON.parse(readFileSync(f, "utf8")).store;
    for (const l of store?.lines ?? []) {
      fixtures.add(l.fixture);
      items.add(l.item);
    }
  }
  return { fixtures: [...fixtures].sort(), items: [...items].sort() };
}

// Measures everything the specs name; returns the fixtures.json object.
export async function measureAll(root) {
  const { measureOne } = await import("../../commands/measure.mjs");
  const { buildStamp } = await import("../../lib/install-api.mjs");
  const want = wanted(root);
  const out = { _generated: "tools\\cli fixtures: boards and footprints measured from the .xob colliders (tools\\cli measure). Do not edit; rerun it when a spec's store block names a new fixture or item", _build: String(buildStamp().buildid), fixtures: {}, items: {} };
  for (const name of want.fixtures) {
    const m = await measureOne(root, name, { minSize: 0.05 });
    const boards = boardsOf(m.surfaces);
    if (!boards.length) throw new Error(`${name}: no surface to stand goods on`);
    out.fixtures[name] = { prefab: m.ref ?? m.path, boards };
  }
  for (const ref of want.items) {
    const m = await measureOne(root, ref, { minSize: 0.05 });
    if (!m.bounds) throw new Error(`${ref}: no bounds`);
    out.items[itemKey(ref)] = itemOf(m.bounds);
  }
  return out;
}

// Differences between two fixtures.json objects, as lines (empty = same). Ignores _generated and _build.
export function diffFixtures(a, b) {
  const out = [];
  for (const sect of ["fixtures", "items"]) {
    for (const k of new Set([...Object.keys(a[sect] ?? {}), ...Object.keys(b[sect] ?? {})])) {
      if (JSON.stringify(a[sect]?.[k]) !== JSON.stringify(b[sect]?.[k])) out.push(`${sect}.${k}: ${JSON.stringify(a[sect]?.[k])} != ${JSON.stringify(b[sect]?.[k])}`);
    }
  }
  return out;
}
